public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // If the given type is not parameterized, return null
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the parameter count for the given type
    int parameterCount = ((ParameterizedType) genericType).getActualTypeArguments().length;

    // If the parameter count is not equal to the type arguments for the target type, return null
    if (parameterCount != targetType.getTypeParameters().length) {
        return null;
    }

    // Create an array to store the resolved type arguments
    Class<?>[] resolvedArguments = new Class[parameterCount];

    // Get the type arguments for the given generic type
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // For each type argument, if the type argument implements all the bounds of the corresponding target type,
    // add it to the resolvedArguments array. Otherwise, return null.
    for (int i = 0; i < parameterCount; i++) {
        Type typeArgument = typeArguments[i];
        TypeVariable<?> var = targetType.getTypeParameters()[i];

        if (!((Class<?>) typeArgument).isAssignableFrom((Class<?>) var.getBounds()[0])) {
            return null;
        }

        resolvedArguments[i] = (Class<?>) typeArgument;
    }

    return resolvedArguments;
}

