private static final int BUFFER_SIZE = 8192;

public byte[] toByteArray() {
    // Calculate the size of the resulting byte array
    int size = (int) Math.ceil((double) this.size() / BUFFER_SIZE) * BUFFER_SIZE;
    // Allocate a new byte array with the calculated size
    byte[] bytes = new byte[size];

    // Copy the data to the byte array in chunks of BUFFER_SIZE bytes
    int bufferSize = 0;
    int readBytes = 0;
    while (readBytes < size) {
        bufferSize = Math.min(BUFFER_SIZE, size - readBytes);
        this.read(bytes, readBytes, bufferSize);
        readBytes += bufferSize;
