public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path or relative path is null");
    }

    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    if (pathParts.length == 0 || relativePathParts.length == 0) {
        throw new IllegalArgumentException("Path or relative path is empty");
    }

    StringBuilder builder = new StringBuilder();
    for (String pathPart : pathParts) {
        if (pathPart.isEmpty()) {
            continue;
        }
        builder.append(pathPart).append("/");
    }

    for (String relativePathPart : relativePathParts) {
        if (relativePathPart.isEmpty()) {
            continue;
        }

        if (relativePathPart.startsWith("..")) {
            int index = builder.lastIndexOf("/");
            if (index != -1) {
                builder.delete(index, builder.length());
            }
        } else if (!relativePathPart.startsWith(".")) {
            builder.append(relativePathPart).append("/");
        }
    }

    return builder.toString();
}

