            threadSnapshots.add(threadSnapshot);
        }
        //Filter the thread snapshots based on the time ranges provided by the client
        List<ThreadSnapshot> filteredThreadSnapshots = threadSnapshots.stream()
                .filter(s -> s.getAlloc() <= timeRanges.get(timeRanges.size()-1).getEndTime())
                .collect(Collectors.toList());
        return filteredThreadSnapshots;
    }
    return new ArrayList<>();
}
